// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

var N_FRAMES = 150;

var N = 40; // grid size for the rectangles packing
var margin = 2; // size of the margin (in grid units)
var maxSize; // max size of each tile (in grid units)
var u, v; // size of the smaller possible tile and size of one spot (in pixels)

var rectangles = []; // all rectangles (tiles)
var spots = []; // all spots

var randInt = (a, b) => (floor(random(a, b))); 

function setup() {
  createCanvas(600, 600);
	pixelDensity(1);
	noStroke();

	maxSize = N/5;
	u = width/N;
	v = u/2;

	let s = 2*randInt(2, maxSize/2);
	rectangles.push({
		i: N/2-s/2,
		j: N/2-s/2,
		si: s,
		sj: s,
		noRay: true
	});

	createComposition();
	createConnections();
	DSatur("offset", [PI/3, 2*PI/3, PI, 4*PI/3, 5*PI/3, TAU], true);
	createSpots();

	describe("Abstract generative art, looping animation. Black background with an irregular grid of square tiles. Inside each tile, a smaller grid of dots. The dots get bigger and smaller, forming concentric wave patterns. Inside each tile, the wave pattern is slightly offset compared to its neighbors. On top of the dots, thin yellow pixelated rays turn around the center, appearing in only some tiles at a time. The rays never appear on the central tile.");
}

function draw() {
	background(5);

	let t = TAU*(frameCount%N_FRAMES)/N_FRAMES;
  for (let sp of spots) {
		drawSpot(sp, t);
	}
}

// creating the composition

function createComposition() {
	let nRects = 1000;
	for (let i = 0; i < nRects; i++) {
    let newRecta = generateRectangle(rectangles);
    if (newRecta.si > 1 || newRecta.sj > 1) {
      rectangles.push(newRecta);
    }
  }

  // fill the gaps with 1x1 rectangles
	for (let i = margin; i < N-margin; i++) {
		for (let j = margin; j < N-margin; j++) {
			var newRecta = {
				i: i,
				j: j,
				si: 1,
				sj: 1
			}
			let canAdd = true;
			for (let recta of rectangles) {
				if (rectanglesIntersect(newRecta, recta)) {
					canAdd = false;
					break;
				}
			}
			if (canAdd) {
				rectangles.push(newRecta);
			}
		}
	}
}

function rectanglesIntersect(recta1, recta2) {
	return ((recta1.i <= recta2.i && recta1.i+recta1.si > recta2.i) || (recta2.i <= recta1.i && recta2.i+recta2.si > recta1.i)) && ((recta1.j <= recta2.j && recta1.j+recta1.sj > recta2.j) || (recta2.j <= recta1.j && recta2.j+recta2.sj > recta1.j));
}

function generateRectangle(rectangles) {
  let i = randInt(margin, N-margin);
  let j = randInt(margin, N-margin);

	// determine biggest possible size
	var s = 0;
	if (rectangles.length == 0) {
		s = min(maxSize, N-i-margin-1, N-j-margin-1);
	} else {
		let intersects = false;
		let _wG_1 = 0; while ((!intersects) && ++_wG_1 < 20000) {
			s++;
			for (let recta of rectangles) {
				if (i+s > N-margin || j+s > N-margin || s > maxSize || rectanglesIntersect({i: i, j: j, si: s, sj: s}, recta)) {
					intersects = true;
					break;
				}
			}
		}
		s--;
	}

  let recta = {
    i: i,
    j: j,
    si: s,
		sj: s
  };
  return recta;
}

// creating the graph

function createConnections() {
	let l = rectangles.length;
	for (let i = 0; i < l; i++) {
		let recta1 = rectangles[i];
		if (!recta1.neighbors) recta1.neighbors = [];
		for (let j = 0; j < l; j++) {
			let recta2 = rectangles[j];
			if (!recta2.neighbors) recta2.neighbors = [];
			if (i != j && rectanglesTouch(recta1, recta2)) {
				recta1.neighbors.push(recta2);
				//recta2.neighbors.push(recta1);
			}
		}
	}
}

function rectanglesTouch(recta1, recta2) {
	if (((recta1.i <= recta2.i && recta1.i+recta1.si == recta2.i) || (recta2.i <= recta1.i && recta2.i+recta2.si == recta1.i)) && ((recta1.j <= recta2.j && recta1.j+recta1.sj > recta2.j) || (recta2.j <= recta1.j && recta2.j+recta2.sj > recta1.j)))
		return true;
	if (((recta1.i <= recta2.i && recta1.i+recta1.si > recta2.i) || (recta2.i <= recta1.i && recta2.i+recta2.si > recta1.i)) && ((recta1.j <= recta2.j && recta1.j+recta1.sj == recta2.j) || (recta2.j <= recta1.j && recta2.j+recta2.sj == recta1.j)))
		return true;
	return false;
}

// coloring the graph

function DSatur(el, elements, shuffleIt) {
	// from https://en.wikipedia.org/wiki/DSatur

	for (let i = 0; i < rectangles.length; i++) {
		// step 1
		let v, vSat = -1, vElementsUsed;
		for (let recta of rectangles) {
			if (!recta[el]) {
				let elementsUsed = elementsUsedByNeighbors(recta, el);
				let sat = elementsUsed.length;
				if (sat > vSat) {
					v = recta;
					vSat = sat;
					vElementsUsed = elementsUsed;
				} else if (sat == vSat) {
					if (largestDegreeInTheSubgraphInducedByTheUncoloredVertices(recta, el) > largestDegreeInTheSubgraphInducedByTheUncoloredVertices(v, el)) {
						v = recta;
						vSat = sat;
						vElementsUsed = elementsUsed;
					}
				}
			}
		}

		// step2
		shuffle(elements, shuffleIt);
		for (let element of elements) {
			if (vElementsUsed.indexOf(element) == -1) {
				v[el] = element;
				break;
			}
		}
	}
}

function elementsUsedByNeighbors(v, el) {
	var elementsUsed = [];
	for (let neigh of v.neighbors) {
		if (neigh[el]) elementsUsed.push(neigh[el]);
	}
	return [...new Set(elementsUsed)];
}

function largestDegreeInTheSubgraphInducedByTheUncoloredVertices(v, el) {
	let largestDegree = -1;
	for (let neigh of v.neighbors) {
		if (!neigh[el]) {
			var sat = elementsUsedByNeighbors(neigh, el);
			if (sat > largestDegree) largestDegree = sat;
		}
	}
	return largestDegree;
}

// drawing

function createSpots() {
	for (let recta of rectangles) {
		let x0 = recta.i*u, y0 = recta.j*u;
		let w = recta.si*u, h = recta.sj*u;

		for (let x = x0+v/2; x < x0+w; x += (Math.max(0.001, Math.abs(v)) || 1)) {
			for (let y = y0+v/2; y < y0+h; y += (Math.max(0.001, Math.abs(v)) || 1)) {
				spots.push({
					x: x,
					y: y,
					offset: recta.offset,
					distToCenter: dist(x, y, width/2, height/2),
					theta: atan2(y-height/2, x-width/2),
					noRay: recta.noRay
				});
			}
		}
	}
}

function drawSpot(sp, t) {
	let density = 30;

	let dVal = (sin(sp.distToCenter/density-t+sp.offset)+1)/2;
	let d = dVal*v*0.6+v*0.2;
	fill("#fffcf2");
	circle(sp.x, sp.y, d);

	let colVal = (sin(2*sp.theta-t+sp.offset)+1)/2;
	if (colVal < 5e-3 && !sp.noRay) {
		fill("#f9d531");
		rect(sp.x-v/2, sp.y-v/2, v);
	}
}
